# I will now get the songs for each playlist using the `show_playlist` API.
# I will collect all songs from all playlists to identify which ones are in the old_songs list.
all_playlist_songs = {}
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    playlist_details = apis.spotify.show_playlist(playlist_id=playlist_id, access_token=spotify_access_token)
    if 'songs' in playlist_details:
        all_playlist_songs[playlist_id] = playlist_details['songs']
    else:
        all_playlist_songs[playlist_id] = []

print(all_playlist_songs)  # To verify the songs fetched for each playlist.

