# old_song_ids is a set of song IDs only, no playlist info.
# I need to find which playlists contain these old songs.
# I will iterate over all playlists and their songs to find which playlists contain these old songs.

# I assume I have all_playlists and song_details from previous steps.
# I will fetch songs from each playlist and check if they are in old_song_ids.

# First, get all playlists again if not already available
if 'all_playlists' not in globals():
    all_playlists = []
    page = 1
    while True:
        playlists_page = apis.spotify.show_playlist_library(access_token=spotify_access_token, page=page)
        all_playlists.extend(playlists_page['playlists'])
        if not playlists_page.get('has_more', False):
            break
        page += 1

# Now, for each playlist, get songs and check if any are in old_song_ids
old_songs_by_playlist = {}

for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    page = 1
    while True:
        songs_page = apis.spotify.show_playlist_songs(access_token=spotify_access_token, playlist_id=playlist_id, page=page)
        for song in songs_page['songs']:
            if song['song_id'] in old_song_ids:
                if playlist_id not in old_songs_by_playlist:
                    old_songs_by_playlist[playlist_id] = []
