# The API to get detailed information about a specific playlist is `show_playlist`.
# I will use `show_playlist` to get the songs in each playlist and find which contain old songs.

# For each playlist, get its details including songs, then check for old songs.
old_songs_by_playlist = {}

for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    playlist_details = apis.spotify.show_playlist(access_token=spotify_access_token, playlist_id=playlist_id)
    # Assuming playlist_details contains a 'songs' key with list of songs
    for song in playlist_details.get('songs', []):
        if song['song_id'] in old_song_ids:
            if playlist_id not in old_songs_by_playlist:
                old_songs_by_playlist[playlist_id] = []
            old_songs_by_playlist[playlist_id].append(song['song_id'])

print(old_songs_by_playlist)

