    line = match.group(0)
    for song, release_month in release_months.items():
        if song in line:
            return line.replace("RELEASED_AT TODO", f"RELEASED_AT {release_month}")
    return line

updated_note_content = re.sub(r".*RELEASED_AT TODO.*", replace_release_month, note_content)

print(updated_note_content)  # Verify the updated note content with release months filled in.

