steps.code:
# The error is due to the use of \1 in the replacement string with an f-string, which causes invalid group reference.
# I will fix it by using a function in re.sub to safely replace the matched text.

def replace_release_month(match):
    matched_text = match.group(0)
    song_title = None
    for song in release_months:
        if song in matched_text:
            song_title = song
            break
    if song_title:
        return matched_text.replace("RELEASED_AT TODO", release_months[song_title])
    return matched_text

# Replace all occurrences of "RELEASED_AT TODO" for songs in release_months
for song in release_months:
    pattern = re.compile(rf"{re.escape(song)}.*?RELEASED_AT TODO", re.DOTALL)
    note_content = pattern.sub(replace_release_month, note_content)

# Now try to find the note_id for "Liked Songs" note again
notes_list = apis.simple_note.list_notes(access_token=simple_note_password, page_index=0, page_limit=50)
note_id = None
for note in notes_list:
    if note.get("title") == "Liked Songs":
        note_id = note.get("note_id")
        break

if note_id:
    update_response = apis.simple_note.update_note(access_token=simple_note_password, note_id=note_id, content=note_content)
else:
    update_response = None

print(update_response)

