   "description": "The title of the playlist.",
   "default": null,
   "constraints": [
    "length >= 1"
   ]
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from spotify app login.",
   "default": null,
   "constraints": []
  },
  {
   "name": "is_public",
   "type": "boolean",
   "required": false,
   "description": "Whether the playlist is public or not.",
   "default": false,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string",
   "playlist_id": 1
  },
  "failure": {
   "message": "string"
  }
 }
}

